  const jwtValidation = parseAndValidateJwt(rawToken);
  if (!jwtValidation.valid) return { status: 401, error: "Unauthorized" };

  const user = jwtValidation.payload;
  const verifiedTenantId = user.tenant_id || user.sub;
  const isSuperAdmin = user.role === "superadmin";
  const resourceId = req.params?.id;

  const target = await db.appointments.findById(resourceId);
  if (!target) return { status: 404, error: "Not Found" };

  // Verificação estrita de BOLA / IDOR:
  if (!isSuperAdmin && target.tenant_id !== verifiedTenantId) {
    return { status: 403, error: "Forbidden", code: "CROSS_TENANT_ACCESS_DENIED" };
  }

  if (req.method === "PUT") {
    const sanitized = { ...req.body };
    delete sanitized.tenant_id; // DESCARTA PARÂMETRO DO CLIENTE
    delete sanitized.id;
    return await db.appointments.update(resourceId, { ...sanitized, tenant_id: target.tenant_id });
  }

  if (req.method === "DELETE") {
    return await db.appointments.delete(resourceId);
  }
